 this.reactionCounts = result.counts;
 this.reactorsCount = result.total;
 // The server caps the list; when it was cut short, filters fetch their own latest reactors.
 this.reactorsComplete = result.reactors.length >= result.total;
 this.loadingReactorsForId = null;
 },
 async setReactorFilter(type) {
 this.reactorFilter = type;
 if (this.reactorsComplete) return;
 this.loadingReactorsForId = this.reactorsCommentId;
 const result = await $wire.loadReactors(this.reactorsCommentId, type === 'all' ? null : type);
 if (this.reactorFilter !== type) return; // a newer filter click owns the list now
 this.reactorsList = result.reactors;
 this.loadingReactorsForId = null;
 },
 closeReactorsModal() {
 this.showReactorsModal = false;
 // Delay clearing data until after fade animation (200ms)
 setTimeout(() => {
 this.reactorsCount = 0;
 this.reactorFilter = 'all';
 this.reactorsList = [];
 this.reactionCounts = {};
 }, 200);
 }
 }"
